                    break;
                case 92 when tag.WireType == 2:
                    value.Message = reader.ReadString();
                    break;
                default:
                    reader.Skip(tag.WireType);
                    break;
            }
        }
        return value;
    }

    public static byte[] Encode(S2C_GetLoginServiceAddr value)
    {
        var writer = new BinaryWriter();
        if (!string.IsNullOrEmpty(value.Name)) writer.WriteString(1, value.Name);
        if (!string.IsNullOrEmpty(value.Ip)) writer.WriteString(2, value.Ip);
        if (value.Port != 0) writer.WriteUInt32(3, value.Port);
        if (value.RpcId != 0) writer.WriteUInt32(90, value.RpcId);
        if (value.Error != 0) writer.WriteUInt32(91, value.Error);
        if (!string.IsNullOrEmpty(value.Message)) writer.WriteString(92, value.Message);
        return writer.ToArray();
    }
}

public static class S2C_LoginCodec
{
    public static S2C_Login Decode(byte[] payload)
    {
        var reader = new BinaryReader(payload);
        var value = new S2C_Login();
        while (!reader.EndOfMessage)
        {
            var tag = reader.ReadTag();
            switch (tag.FieldNumber)
            {
                case 1 when tag.WireType == 2:
                    value.Account = reader.ReadString();
                    break;
                case 2 when tag.WireType == 2:
                    value.Service = reader.ReadString();
                    break;
                case 3 when tag.WireType == 0:
                    value.LoginCount = reader.ReadUInt32();
                    break;
                case 4 when tag.WireType == 2:
                    value.Token = reader.ReadString();
                    break;
                case 5 when tag.WireType == 2:
                    value.GateName = reader.ReadString();
                    break;
                case 6 when tag.WireType == 2:
                    value.GateIp = reader.ReadString();
                    break;
                case 7 when tag.WireType == 0:
                    value.GatePort = reader.ReadUInt32();
                    break;
                case 90 when tag.WireType == 0:
                    value.RpcId = reader.ReadUInt32();
                    break;
                case 91 when tag.WireType == 0:
                    value.Error = reader.ReadUInt32();
                    break;
                case 92 when tag.WireType == 2:
                    value.Message = reader.ReadString();
                    break;
                default:
                    reader.Skip(tag.WireType);
                    break;
            }
        }
        return value;
    }

    public static byte[] Encode(S2C_Login value)
    {
        var writer = new BinaryWriter();
        if (!string.IsNullOrEmpty(value.Account)) writer.WriteString(1, value.Account);
        if (!string.IsNullOrEmpty(value.Service)) writer.WriteString(2, value.Service);
        if (value.LoginCount != 0) writer.WriteUInt32(3, value.LoginCount);
        if (!string.IsNullOrEmpty(value.Token)) writer.WriteString(4, value.Token);
        if (!string.IsNullOrEmpty(value.GateName)) writer.WriteString(5, value.GateName);
        if (!string.IsNullOrEmpty(value.GateIp)) writer.WriteString(6, value.GateIp);
        if (value.GatePort != 0) writer.WriteUInt32(7, value.GatePort);
        if (value.RpcId != 0) writer.WriteUInt32(90, value.RpcId);
        if (value.Error != 0) writer.WriteUInt32(91, value.Error);
        if (!string.IsNullOrEmpty(value.Message)) writer.WriteString(92, value.Message);
        return writer.ToArray();
    }
}

public static class UnitNumericDeltaCodec
{
    public static UnitNumericDelta Decode(byte[] payload)
    {
        var reader = new BinaryReader(payload);
        var value = new UnitNumericDelta();
        while (!reader.EndOfMessage)
        {
            var tag = reader.ReadTag();
            switch (tag.FieldNumber)
            {
                case 1 when tag.WireType == 0:
                    value.UnitId = reader.ReadUInt32();
                    break;
                case 2 when tag.WireType == 0:
                    value.NumericType = reader.ReadUInt32();
                    break;
                case 3 when tag.WireType == 0:
                    value.Value = reader.ReadInt64();
                    break;
                default:
                    reader.Skip(tag.WireType);
                    break;
            }
        }
        return value;
    }

    public static byte[] Encode(UnitNumericDelta value)
    {
        var writer = new BinaryWriter();
        if (value.UnitId != 0) writer.WriteUInt32(1, value.UnitId);
        if (value.NumericType != 0) writer.WriteUInt32(2, value.NumericType);
        if (value.Value != 0) writer.WriteInt64(3, value.Value);
        return writer.ToArray();
    }
}

public static class UnitStateDeltaCodec
{
    public static UnitStateDelta Decode(byte[] payload)
    {
        var reader = new BinaryReader(payload);
        var value = new UnitStateDelta();
        while (!reader.EndOfMessage)
        {
            var tag = reader.ReadTag();
            switch (tag.FieldNumber)
            {
                case 1 when tag.WireType == 0:
                    value.UnitId = reader.ReadUInt32();
                    break;
                case 2 when tag.WireType == 0:
                    value.DirtyMaskLow = reader.ReadUInt32();
                    break;
                case 3 when tag.WireType == 0:
                    value.DirtyMaskHigh = reader.ReadUInt32();
                    break;
                case 4 when tag.WireType == 5:
                    value.X = reader.ReadFloat();
                    break;
                case 5 when tag.WireType == 5:
                    value.Y = reader.ReadFloat();
                    break;
                case 6 when tag.WireType == 5:
                    value.SpeedCellsPerSecond = reader.ReadFloat();
                    break;
                case 7 when tag.WireType == 0:
                    value.Alive = reader.ReadBool();
                    break;
                case 8 when tag.WireType == 5:
                    value.Z = reader.ReadFloat();
                    break;
                case 9 when tag.WireType == 5:
                    value.Yaw = reader.ReadFloat();
                    break;
                default:
                    reader.Skip(tag.WireType);
                    break;
            }
        }
        return value;
    }

    public static byte[] Encode(UnitStateDelta value)
    {
        var writer = new BinaryWriter();
        if (value.UnitId != 0) writer.WriteUInt32(1, value.UnitId);
        if (value.DirtyMaskLow != 0) writer.WriteUInt32(2, value.DirtyMaskLow);
        if (value.DirtyMaskHigh != 0) writer.WriteUInt32(3, value.DirtyMaskHigh);
        if (value.X != 0) writer.WriteFloat(4, value.X);
        if (value.Y != 0) writer.WriteFloat(5, value.Y);
        if (value.SpeedCellsPerSecond != 0) writer.WriteFloat(6, value.SpeedCellsPerSecond);
        if (value.Alive) writer.WriteBool(7, value.Alive);
        if (value.Z != 0) writer.WriteFloat(8, value.Z);
        if (value.Yaw != 0) writer.WriteFloat(9, value.Yaw);
        return writer.ToArray();
    }
}

